H('109.d.4.C',3,"A conductor is a material that:","Allows current to flow easily",["Blocks current","Absorbs sound","Reflects light"],"Conductors carry current.")
H('109.d.4.C',4,"Which of these is a good insulator?","Rubber",["Copper","Silver","Aluminum"],"Rubber blocks current.")
H('109.d.4.D',3,"The unit used to measure electric current is the:","Ampere",["Volt","Ohm","Watt"],"Amps measure current.")
H('109.d.4.D',4,"The unit used to measure resistance is the:","Ohm",["Ampere","Volt","Hertz"],"Ohms measure resistance.")
H('109.d.4.E',3,"If voltage rises and resistance stays the same, current:","Increases",["Decreases","Stops","Stays zero"],"Current is proportional to voltage.")
H('109.d.4.E',4,"If resistance rises and voltage stays the same, current:","Decreases",["Increases","Doubles","Stays the same"],"Inverse to resistance.")
H('109.d.4.F',3,"By Ohm's law, a 12-volt source across a 6-ohm resistor produces a current of:","2 amperes",["72 amperes","0.5 amperes","18 amperes"],"I = V/R = 12/6 = 2.")
